design.css:
/* Booth — the Miruro look (docs/theme-references/miruro.md, tmp/parity/booth/measure.md): #080808 page,
   #0E0E0E panels, #141414 controls, Geist, one lavender accent, 8 px corners, hairline borders, glass. */

/* ── Top bar: #0E0E0E with a hairline under it, 40 px squares, a centred 463 × 42 search field. The row is
   the site's whole 62.6 px bar (9.6 + 42.4 + 9.6 + hairline), under izumi's 32 px title-bar band. ── */
:scope { --theme-top-row: 62.6px; }
[data-slot="nav.top"] { background: #0e0e0e !important; border-bottom: 1px solid rgba(245, 245, 245, 0.1) !important; padding-left: 9.6px !important; padding-right: 9.6px !important; }
/* Destinations live in the drawer; the bar keeps the menu, the wordmark, search and the account controls. */
[data-slot="nav.top"] > [data-part="nav.item"] { display: none; }
[data-slot="nav.top"] > [data-part="nav.menu"],
[data-slot="nav.top"] [data-part="nav.action"] { width: 40.4px; height: 40.4px; border: 1px solid rgba(245, 245, 245, 0.1); border-radius: 8px; background: #141414; color: #e8e8e8; }
[data-slot="nav.top"] > [data-part="nav.menu"] svg { width: 19.2px; height: 19.2px; }
[data-slot="nav.top"] form:has([data-part="search.field"]) { width: 100%; max-width: 463.3px; margin: 0 auto; }
[data-slot="nav.top"] [data-part="search.field"] { height: 42.4px; padding-left: 37.8px; padding-right: 44px; border: 1px solid rgba(245, 245, 245, 0.1); border-radius: 8px; background: #141414; color: #e8e8e8; font-size: 13.6px; }
[data-slot="nav.top"] [data-part="search.field"]::placeholder { color: #757575; }
[data-slot="nav.top"] form:has([data-part="search.field"]) > svg { left: 14.6px; width: 19.2px; height: 19.2px; color: #e8e8e8; opacity: 0.5; }
/* The ⌘ shortcut hint at the field's right end (the site's search box shows it). */
[data-slot="nav.top"] form:has([data-part="search.field"])::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 14.6px;
  width: 19.2px;
  height: 19.2px;
  margin-top: -9.6px;
  background: #e8e8e8;
  opacity: 0.5;
  pointer-events: none;
  -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27M15%206v12a3%203%200%201%200%203-3H6a3%203%200%201%200%203%203V6a3%203%200%201%200-3%203h12a3%203%200%201%200-3-3%27%2F%3E%3C%2Fsvg%3E) center / contain no-repeat;
  mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27M15%206v12a3%203%200%201%200%203-3H6a3%203%200%201%200%203%203V6a3%203%200%201%200-3%203h12a3%203%200%201%200-3-3%27%2F%3E%3C%2Fsvg%3E) center / contain no-repeat;
}

/* ── Featured card: 480 px, inset 10 px, 8 px corners, the site's three-way #080808 shade. ── */
[data-slot="home.hero"] { margin: 10px 10px 8px !important; width: auto !important; border-radius: 8px; overflow: hidden; }
[data-slot="home.hero"][data-variant="template"] { height: 480px !important; }
[data-part="booth.hero"] { line-height: normal; }
[data-part="booth.hero"]::after {
  background: linear-gradient(45deg, #080808 5%, rgba(0, 0, 0, 0) 60%), linear-gradient(0deg, #080808 1%, rgba(0, 0, 0, 0) 60%), linear-gradient(-45deg, #080808 5%, rgba(0, 0, 0, 0) 60%) !important;
}
/* Glass: 30% #0E0E0E, a hairline, blur(10px) contrast(1.25). */
[data-part="booth.badge"], [data-part="booth.prev"], [data-part="booth.next"], [data-part="booth.fraction"],
[data-part="booth.pill"], [data-part="booth.details"], [data-part="booth.watch"] {
  background: rgba(14, 14, 14, 0.3) !important;
  border: 1px solid rgba(245, 245, 245, 0.1);
  -webkit-backdrop-filter: blur(10px) contrast(1.25);
  backdrop-filter: blur(10px) contrast(1.25);
  color: #e8e8e8;
}
/* The hero's own rule pads every layer's bottom for its markers; these boxes keep the site's padding. */
[data-part="booth.badge"] { margin: 16px; padding: 8px 9.6px !important; }
[data-part="booth.countdown"] { text-transform: uppercase; }
[data-part="booth.pager"] { margin: 16px; padding: 0 !important; }
[data-part="booth.prev"], [data-part="booth.next"] { width: 38px; height: 38px; min-height: 38px !important; padding: 0 !important; justify-content: center; }
[data-part="hero.edge"] { display: none !important; }
[data-part="booth.fraction"] { min-width: 70px !important; padding: 8px !important; align-items: baseline !important; }
/* The copy block: half the card, centred text, 16 px from the corner. */
[data-part="booth.info"] { box-sizing: content-box !important; max-width: 50%; margin: 16px; }
[data-part="booth.pill"] { padding: 4.8px 9.6px; }
/* The title fills with the cover's colour fading to white, as on the site. */
[data-part="booth.title"] {
  background-image: linear-gradient(45deg, rgb(var(--hero-ambient-rgb, 181 168 255)), #fff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  line-height: normal;
  text-shadow: none !important;
}
[data-part="booth.synopsis"] { line-height: 1.2; }
[data-part="booth.corner"] { margin: 16px; padding: 0 !important; }
[data-part="booth.details"], [data-part="booth.watch"] { padding: 12px 13.6px !important; gap: 4px !important; line-height: normal; }
[data-part="booth.details"] svg { width: 20px; height: 20px; }
/* Filled info and play discs, as the site's icons. */
[data-part="booth.details"] svg circle { fill: currentColor; }
[data-part="booth.details"] svg path { stroke: #080808; }
[data-part="booth.watch"] svg { width: 18px; height: 18px; padding: 4.5px 3.5px 4.5px 5px; border-radius: 50%; background: #e8e8e8; color: #080808; }

/* Phone card: 374 × 416, 8 px inset; facts and title centred over two equal pills along the bottom. */
[data-part="booth.mbottom"] { inset-inline-end: 0; margin: 16px; padding: 0 !important; }
[data-part="booth.mactions"] > [data-part="booth.details"], [data-part="booth.mactions"] > [data-part="booth.watch"] { flex: 1 1 0; justify-content: center; padding: 2.4px 4px !important; }
[data-part="booth.mactions"] [data-part="booth.watch"] svg { width: 20px; height: 20px; padding: 5px 4px 5px 6px; }
/* ── Genre chip rail: 12 px 36 px around a masked scroller of #141414 chips. ── */
[data-slot="block.genre-chips"] { margin-bottom: 8px !important; padding: 12px 46px !important; }
[data-slot="block.genre-chips"] :has(> [data-part="chip"]) {
  flex-wrap: nowrap;
  gap: 8px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  -webkit-mask-image: linear-gradient(90deg, rgba(0, 0, 0, 0), #000 10%, #000 90%, rgba(0, 0, 0, 0));
  mask-image: linear-gradient(90deg, rgba(0, 0, 0, 0), #000 10%, #000 90%, rgba(0, 0, 0, 0));
}
[data-slot="block.genre-chips"] [data-part="chip"] { height: auto; padding: 8px 28px; border: 0; border-radius: 8px; background: #141414; color: #e8e8e8; font-size: 12.8px; font-weight: 500; line-height: normal; white-space: nowrap; flex-shrink: 0; }

/* ── Main column + aside: 10 px page inset, 24 px gutter, 384 px aside. ── */
[data-slot="home.aside"] { padding-right: 10px; }
[data-slot="home.main"] [data-slot="row"] { margin-bottom: 16px !important; }
[data-slot="home.main"] [data-slot="row"] [data-part="row.header"],
[data-slot="home.main"] [data-slot="row"] [data-part="row.track"] { padding-left: 10px !important; padding-right: 10px !important; }

/* NEWEST / POPULAR / TOP RATED in a hairline strip, the ‹ 1 › pager at its right, 32 px poster grid. */
[data-slot="block.tabbed-grid"] { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; column-gap: 8px; padding: 0 0 0 10px !important; }
[data-slot="block.tabbed-grid"] > * { grid-column: 1 / -1; }
[data-slot="block.tabbed-grid"] > div:has(> [data-part="tabs"]) { grid-column: 1; grid-row: 1; }
[data-slot="block.tabbed-grid"] [data-part="block.grid"] { gap: 32px !important; margin-top: 16px; }
[data-slot="block.tabbed-grid"] [data-part="tabs"] { margin: 0 !important; display: flex; gap: 0; padding: 0; width: fit-content; max-width: 100%; border: 1px solid rgba(245, 245, 245, 0.1); border-radius: 8px; background: transparent; overflow: hidden; }
[data-slot="block.tabbed-grid"] [data-part="tab"] { min-height: 0 !important; height: auto !important; padding: 12px 20px !important; border-radius: 0 !important; background: #141414 !important; color: #e8e8e8 !important; font-size: 12.8px !important; font-weight: 500 !important; line-height: normal !important; box-shadow: none !important; }
[data-slot="block.tabbed-grid"] [data-part="tab"][data-active] { background: rgba(181, 168, 255, 0.25) !important; color: #b5a8ff !important; }
[data-slot="block.tabbed-grid"] [data-part="tab"] > span { display: none; }
/* The site's compact pager: ‹ [current page] › in one hairline box. */
[data-slot="block.tabbed-grid"] > [data-part="pagination"] { grid-column: 2; grid-row: 1; flex-wrap: nowrap; gap: 0; margin: 0; border: 1px solid rgba(245, 245, 245, 0.1); border-radius: 8px; overflow: hidden; }
[data-slot="block.tabbed-grid"] [data-part="page-step"], [data-slot="block.tabbed-grid"] [data-part="page-number"] { width: 37.3px; height: 33.3px; min-width: 0; padding: 0; border-radius: 0; background: #141414; color: #e8e8e8; font-size: 13.33px; font-weight: 400; }
[data-slot="block.tabbed-grid"] [data-part="page-step"]:disabled { opacity: 0.5; }
[data-slot="block.tabbed-grid"] [data-part="page-step"] svg { width: 13.3px; height: 13.3px; }
[data-slot="block.tabbed-grid"] > [data-part="pagination"] > [data-part="page-number"] { width: 40px; opacity: 0.5; }
[data-slot="block.tabbed-grid"] > [data-part="pagination"] > [data-part="page-number"]:not([data-active]),
[data-slot="block.tabbed-grid"] > [data-part="pagination"] > span { display: none; }

/* Poster cards: 174 × 241 art, a status dot before the 13.28 px title, grey 12 px detail chips. */
[data-part="booth.poster"] { aspect-ratio: 174 / 240.66 !important; background: rgba(85, 85, 85, 0.1); }
[data-part="booth.name"] { margin-top: 1.6px; padding: 6.4px 4.8px; line-height: normal; }
[data-part="booth.airing"], [data-part="booth.finished"] { flex: 0 0 8px; width: 8px; height: 8px; border-radius: 50%; }
[data-part="booth.airing"] { background: #aaff00; }
[data-part="booth.finished"] { background: #00aaff; }
[data-part="booth.detail"] { height: 22.4px; padding: 3.2px; background: #141414; line-height: normal; }

/* ── TOP AIRING aside panel: #0E0E0E, hairline, 12 px padding, 96 px #141414 rows. ── */
[data-slot="block.ranked-list"] { margin-bottom: 16px !important; padding: 12px !important; border: 1px solid rgba(245, 245, 245, 0.1); border-radius: 8px; background: #0e0e0e; }
[data-slot="block.ranked-list"] [data-part="block.title"] { display: flex; align-items: center; gap: 4px; margin: 0; padding: 4px 0 16px; font-size: 17.6px; font-weight: 700; line-height: normal; }
[data-slot="block.ranked-list"] [data-part="block.title"]::before {
  content: "";
  width: 17.6px;
  height: 17.6px;
  background: currentColor;
  -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27m9%2018%206-6-6-6%27%2F%3E%3C%2Fsvg%3E) center / contain no-repeat;
  mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27m9%2018%206-6-6-6%27%2F%3E%3C%2Fsvg%3E) center / contain no-repeat;
}
[data-slot="block.ranked-list"] ol { display: flex; flex-direction: column; gap: 8px; }
[data-slot="block.ranked-list"] ol > li { margin: 0 !important; }
[data-part="booth.rk"] { height: 96px; background: #141414; line-height: normal; transition: background-color 0.2s ease-in-out; }
[data-part="block.item"]:hover > * > [data-part="booth.rk"] { background: #1c1c1c; }
/* The banner fills the right 60 % under the site's -70° #141414 fade. */
[data-part="booth.rk-banner"] { inset: 0 0 0 auto !important; width: 60% !important; }
[data-part="booth.rk-banner"]::after { content: ""; position: absolute; inset: 0; background: linear-gradient(-70deg, rgba(0, 0, 0, 0) -200%, #141414 80%); }
[data-part="booth.rk-cover"] { flex: 0 0 68px; width: 68px !important; height: 96px; background: rgba(85, 85, 85, 0.1); box-shadow: 0 0 10px rgba(0, 0, 0, 0.6); }
[data-part="booth.rk-name"] span { color: #e8e8e8; }
[data-part="booth.rk-facts"] { height: 26px; margin-left: 24px; }
[data-part="booth.rk-chip"] { padding: 1.6px 3.2px; background: rgba(85, 85, 85, 0.1); }

/* Rows. */
[data-part="row.title"], [data-part="block.title"] { font-weight: 700; color: #e8e8e8; }

/* ── Series page (desktop): a 320 px inset banner fading out, a 224 px poster column with the facts card,
   the title, cover-tinted chips, an equal-tab strip and a bordered panel beside it. ── */
[data-slot="detail.banner"][data-variant="desktop"] { height: 320px !important; margin: 10px 10px 0 !important; border-radius: 8px; overflow: hidden; -webkit-mask-image: linear-gradient(#000, rgba(0, 0, 0, 0)); mask-image: linear-gradient(#000, rgba(0, 0, 0, 0)); }
[data-slot="detail.banner"][data-variant="desktop"] > div:has([data-part="hero.slide"]) { top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important; }
[data-slot="detail.banner"][data-variant="desktop"] [data-part="hero.slide"] { opacity: 1 !important; animation: none !important; }
[data-slot="detail.banner"][data-variant="desktop"] [data-part="hero.scrim"] { display: none; }
[data-slot="detail"][data-variant="desktop"] > [data-part="detail.content"] { margin-top: -160px !important; padding: 0 9.6px 64px 41.6px !important; }
[data-slot="detail"][data-variant="desktop"] div:has(> [data-slot="detail.column"]) { gap: 16px !important; }
[data-slot="detail.column"] { gap: 16px !important; }
[data-slot="detail"] [data-part="detail.poster"] { border-radius: 8px; }
[data-slot="detail.column"] [data-part="detail.poster"] { aspect-ratio: 224 / 284.4; height: auto; object-fit: cover; background: #0e0e0e; box-shadow: 0 0 10px rgba(0, 0, 0, 0.6); }
/* Facts card: bold label over a light grey value. */
[data-slot="detail.column"] [data-part="detail.facts"] { display: flex !important; flex-direction: column; align-items: flex-start; gap: 8px; margin: 0; padding: 16px; border: 1px solid rgba(245, 245, 245, 0.1); border-radius: 8px; background: #0e0e0e; }
[data-slot="detail.column"] [data-part="fact"] { display: flex !important; flex-direction: column; gap: 8px; width: 100%; padding: 0 !important; border: 0 !important; background: none !important; font-size: 14.4px; line-height: normal; }
[data-slot="detail.column"] [data-part="fact.label"] { color: #e8e8e8 !important; font-size: 14.4px !important; font-weight: 500 !important; text-transform: none !important; letter-spacing: 0 !important; }
[data-slot="detail.column"] [data-part="fact.value"] { color: #696969 !important; font-size: 14.4px !important; font-weight: 300 !important; text-align: start !important; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.alt-title"] { display: none; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.title"] { margin: 0 0 8px !important; color: #e8e8e8; font-size: 24px !important; font-weight: 700 !important; line-height: 25.6px !important; text-shadow: none !important; }
[data-slot="detail"] [data-part="detail.header"] { margin-bottom: 16px !important; }
/* Chips in the cover's colour, their text the same colour at 45% toward black. */
[data-part="booth.tag"] { padding: 2.4px 6.4px; background-color: rgb(var(--cover-rgb, 181 168 255)); color: color-mix(in srgb, rgb(var(--cover-rgb, 181 168 255)) 45%, #000); line-height: 17.6px; }
[data-slot="detail"] [data-part="detail.meta"] { display: none; }
/* Actions: #141414 8 px buttons, 13.6 px bold. */
[data-slot="detail"][data-variant="desktop"] [data-part="detail.actions"] { gap: 8px !important; margin-bottom: 16px; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.actions"] > button { min-height: 0 !important; height: 35.6px !important; padding: 8px 12px !important; border: 1px solid rgba(245, 245, 245, 0.1) !important; border-radius: 8px !important; background: #0e0e0e !important; color: #e8e8e8 !important; font-size: 13.6px !important; font-weight: 700 !important; box-shadow: none !important; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.actions"] > [data-action="play"] { width: 180.4px; justify-content: center; border-color: transparent !important; background: #141414 !important; text-transform: uppercase; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.actions"] > button svg { width: 13.6px; height: 13.6px; }
/* The section tabs: equal buttons in a #0E0E0E hairline strip, the active one lavender-tinted. */
[data-slot="detail"] [data-part="tabs"][data-variant="bar"] { gap: 4px !important; margin-bottom: 16px !important; padding: 4px !important; border: 1px solid rgba(245, 245, 245, 0.1); border-radius: 8px; background: #0e0e0e !important; }
[data-slot="detail"] [data-part="tabs"][data-variant="bar"] [data-part="tab"] { min-height: 0 !important; height: auto !important; padding: 9.6px 32px !important; border-radius: 8px !important; background: #141414 !important; color: #696969 !important; font-size: 13.33px !important; font-weight: 400 !important; line-height: 16px !important; box-shadow: none !important; }
[data-slot="detail"] [data-part="tabs"][data-variant="bar"] [data-part="tab"][data-active] { background: rgba(181, 168, 255, 0.25) !important; color: #b5a8ff !important; }
[data-slot="detail"] [data-part="detail.synopsis"] { color: #696969; font-size: 13.6px; line-height: 20.8px; }
[data-slot="detail"] [data-part="button"][data-variant="primary"] { border-radius: 8px; background: #141414; color: #e8e8e8; font-weight: 700; }
/* Overview: one #0E0E0E hairline panel, 12 px padding, the synopsis in 13.6 px grey. */
[data-slot="detail"][data-variant="desktop"] div:has(> [data-part="tabs"]) > div:has(> [data-part="detail.synopsis"]) { display: flex; flex-direction: column; gap: 12px; max-width: none !important; margin-bottom: 16px; padding: 12px; border: 1px solid rgba(245, 245, 245, 0.1); border-radius: 8px; background: #0e0e0e; }
[data-slot="detail"][data-variant="desktop"] div:has(> [data-part="tabs"]) > div > [data-part="detail.synopsis"] { max-width: none; margin: 0; }
[data-slot="detail"][data-variant="desktop"] [data-part="detail.actions"] > [data-action="play"] svg { fill: currentColor; }
/* Related and recommended titles: one row of 192 px posters 8 px apart. */
[data-slot="detail.relations"], [data-slot="detail.recommended"] { display: flex !important; gap: 8px !important; overflow-x: auto; overflow-y: hidden; scrollbar-width: none; }
[data-slot="detail.relations"] > *, [data-slot="detail.recommended"] > * { flex: 0 0 192px; width: 192px !important; }
[data-slot="detail"] [data-slot="detail.section"] { margin-top: 16px; }
[data-slot="detail.relations"] [data-part="card"] { width: 100% !important; }
/* Section headings: 24 px bold capitals after a chevron, as RECOMMENDATIONS. */
[data-slot="detail"] [data-part="detail.section-title"] { display: flex; align-items: center; gap: 0; font-size: 24px !important; font-weight: 700 !important; line-height: normal !important; text-transform: uppercase; }
[data-slot="detail"] [data-part="detail.section-title"]::before { content: ""; width: 24px; height: 24px; background: currentColor; -webkit-mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27m9%2018%206-6-6-6%27%2F%3E%3C%2Fsvg%3E) center / contain no-repeat; mask: url(data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%20stroke-linejoin%3D%27round%27%3E%3Cpath%20d%3D%27m9%2018%206-6-6-6%27%2F%3E%3C%2Fsvg%3E) center / contain no-repeat; }

/* Watch History (the site's continue row): 377 px 16:9 stills with 8 px corners, "EP 13" on a 75% black
   8 px chip at the bottom left, a 4 px red progress bar along the bottom, the title in 12.8 px below. */
[data-part="booth.cw-ep"] { margin: 0 0 12px 8px !important; padding: 2px 8px; border-radius: 8px; background: rgba(0, 0, 0, 0.75); }
[data-part="booth.cw-bar"] { height: 4px !important; background: transparent !important; }
